ated":""},{"name":"name","type":"text","not_null":false,"default":null,"identity":"","generated":""},{"name":"created_at","type":"timestamp with time zone","not_null":false,"default":null,"identity":"","generated":""},{"name":"revoked_at","type":"timestamp with time zone","not_null":false,"default":null,"identity":"","generated":""},{"name":"model","type":"text","not_null":false,"default":null,"identity":"","generated":""},{"name":"managed_at","type":"timestamp with time zone","not_null":false,"default":null,"identity":"","generated":""}],"constraints":[],"indexes":[],"triggers":[],"policies":[],"view_sha256":"abdbcd839045189fa68a9013b9c575af33060c7254de7c491f6475f9acceadd5"},{"section":"relation","schema":"swarm_read","name":"agent_runs","kind":"v","owner":"swarm_admin","rls":false,"force_rls":false,"options":["security_barrier=true"],"acl":"{swarm_admin=arwdDxtm/swarm_admin,authenticated=r/swarm_admin,swarm_read=r/swarm_admin}","columns":[{"name":"run_id","type":"uuid","not_null":false,"default":null,"identity":"","generated":""},{"name":"principal_id","type":"uuid","not_null":false,"default":null,"identity":"","generated":""},{"name":"device_id","type":"uuid","not_null":false,"default":null,"identity":"","generated":""},{"name":"started_at","type":"timestamp with time zone","not_null":false,"default":null,"identity":"","generated":""},{"name":"ended_at","type":"timestamp with time zone","not_null":false,"default":null,"identity":"","generated":""}],"constraints":[],"indexes":[],"triggers":[],"policies":[],"view_sha256":"a3b18a1f9fcafa0991bdc3b90dc50f940988cde5226526a0f7639899503e4d8a"},{"section":"relation","schema":"swarm_read","name":"my_devices","kind":"v","owner":"swarm_admin","rls":false,"force_rls":false,"options":["security_barrier=true"],"acl":"{swarm_admin=arwdDxtm/swarm_admin,authenticated=r/swarm_admin,swarm_read=r/swarm_admin}","columns":[{"name":"device_id","type":"uuid","not_null":false,"default":null,"identity":"","generated":""},{"name":"user_id","type":"uuid","not_null":false,"default":null,"identity":"","generated":""},{"name":"label","type":"text","not_null":false,"default":null,"identity":"","generated":""},{"name":"created_at","type":"timestamp with time zone","not_null":false,"default":null,"identity":"","generated":""},{"name":"revoked_at","type":"timestamp with time zone","not_null":false,"default":null,"identity":"","generated":""},{"name":"last_seen_at","type":"timestamp with time zone","not_null":false,"default":null,"identity":"","generated":""}],"constraints":[],"indexes":[],"triggers":[],"policies":[],"view_sha256":"4782e4794c4f2a680e91799162a9f4e20a3f01e2f3aa84d9e47fc661b6d747e0"},{"section":"guard","name":"swarm.agent_join_credentials_guard()","owner":"swarm_admin","language":"plpgsql","return_type":"trigger","security_definer":false,"volatility":"v","strict":false,"leakproof":false,"parallel":"u","config":["search_path=pg_catalog"],"acl":"{swarm_admin=X/swarm_admin}","prosrc_sha256":"4137cb9b07d259778e9efc9295bcf202b4d60a489edd6c005238a95b8a2299f5"},{"section":"guard","name":"swarm.agent_join_attempts_guard()","owner":"swarm_admin","language":"plpgsql","return_type":"trigger","security_definer":false,"volatility":"v","strict":false,"leakproof":false,"parallel":"u","config":["search_path=pg_catalog"],"acl":"{swarm_admin=X/swarm_admin}","prosrc_sha256":"681673ce89ae4d9892d085dc0da5970f746e1a5dd949a344d17e419a9af5ba5b"},{"section":"dependency_index","name":"agent_principals_principal_workspace_owner","valid":true,"ready":true,"unique":true,"definition":"CREATE UNIQUE INDEX agent_principals_principal_workspace_owner ON swarm.agent_principals USING btree (principal_id, workspace_id, owner_user_id)"},{"section":"dependency_index","name":"agent_tokens_token_principal_run","valid":true,"ready":true,"unique":true,"definition":"CREATE UNIQUE INDEX agent_tokens_token_principal_run ON swarm.agent_tokens USING btree (token_id, principal_id, run_id)"},{"section":"idempotency_constraint","name":"idempotency_keys_principal_kind_check","validated":true,"definition":"CHECK (principal_kind = ANY (ARRAY['user'::text, 'agent'::text, 'join'::text]))"}]$h0expected$::jsonb;
  item jsonb; actual jsonb; obj oid; field text; role_name text; privilege_name text;
BEGIN
  FOR item IN SELECT value FROM jsonb_array_elements(expected) LOOP
    IF item->>'section' = 'relation' THEN
      obj := to_regclass(format('%I.%I', item->>'schema', item->>'name'));
      IF obj IS NULL THEN RAISE EXCEPTION 'H0 relation missing: %', item->>'name'; END IF;
      SELECT jsonb_build_object('kind', c.relkind, 'owner', pg_get_userbyid(c.relowner),
        'rls', c.relrowsecurity, 'force_rls', c.relforcerowsecurity,
        'options', to_jsonb(c.reloptions), 'acl', c.relacl::text) INTO actual
      FROM pg_class c WHERE c.oid=obj;
      FOREACH field IN ARRAY ARRAY['kind','owner','rls','force_rls','options','acl'] LOOP
        IF actual->field IS DISTINCT FROM item->field THEN
          RAISE EXCEPTION 'H0 relation % mismatch: %', item->>'name', field;
        END IF;
      END LOOP;
      SELECT COALESCE(jsonb_agg(jsonb_build_object('name', a.attname,
        'type', format_type(a.atttypid,a.atttypmod), 'not_null',a.attnotnull,
        'default',pg_get_expr(ad.adbin,ad.adrelid,true), 'identity',a.attidentity,
        'generated',a.attgenerated) ORDER BY a.attnum),'[]'::jsonb) INTO actual
      FROM pg_attribute a LEFT JOIN pg_attrdef ad ON ad.adrelid=a.attrelid AND ad.adnum=a.attnum
      WHERE a.attrelid=obj AND a.attnum>0 AND NOT a.attisdropped;
      IF actual IS DISTINCT FROM item->'columns' THEN RAISE EXCEPTION 'H0 columns mismatch: %',item->>'name'; END IF;
      SELECT COALESCE(jsonb_agg(jsonb_build_object('name',c.conname,'type',c.contype,
        'validated',c.convalidated,'deferrable',c.condeferrable,'deferred',c.condeferred,
        'definition',pg_get_constraintdef(c.oid,true)) ORDER BY c.conname),'[]'::jsonb) INTO actual
      FROM pg_constraint c WHERE c.conrelid=obj;
      IF actual IS DISTINCT FROM item->'constraints' THEN RAISE EXCEPTION 'H0 constraints mismatch: %',item->>'name'; END IF;
      SELECT COALESCE(jsonb_agg(jsonb_build_object('name',c.relname,'valid',i.indisvalid,
        'ready',i.indisready,'unique',i.indisunique,'definition',pg_get_indexdef(i.indexrelid)) ORDER BY c.relname),'[]'::jsonb) INTO actual
      FROM pg_index i JOIN pg_class c ON c.oid=i.indexrelid WHERE i.indrelid=obj;
      IF actual IS DISTINCT FROM item->'indexes' THEN RAISE EXCEPTION 'H0 indexes mismatch: %',item->>'name'; END IF;
      SELECT COALESCE(jsonb_agg(jsonb_build_object('name',t.tgname,'enabled',t.tgenabled,
        'definition',pg_get_triggerdef(t.oid,true)) ORDER BY t.tgname),'[]'::jsonb) INTO actual
      FROM pg_trigger t WHERE t.tgrelid=obj AND NOT t.tgisinternal;
      IF actual IS DISTINCT FROM item->'triggers' THEN RAISE EXCEPTION 'H0 triggers mismatch: %',item->>'name'; END IF;
      SELECT COALESCE(jsonb_agg(jsonb_build_object('name',p.polname,'permissive',p.polpermissive,
        'command',p.polcmd,'roles',(SELECT jsonb_agg(CASE WHEN id=0 THEN 'public' ELSE pg_get_userbyid(id)::text END ORDER BY id) FROM unnest(p.polroles) id),
        'using',pg_get_expr(p.polqual,p.polrelid,true),'check',pg_get_expr(p.polwithcheck,p.polrelid,true)) ORDER BY p.polname),'[]'::jsonb) INTO actual
      FROM pg_policy p WHERE p.polrelid=obj;
      IF actual IS DISTINCT FROM item->'policies' THEN RAISE EXCEPTION 'H0 policies mismatch: %',item->>'name'; END IF;
      IF item->>'kind'='v' THEN
        IF encode(sha256(convert_to(pg_get_viewdef(obj,true),'UTF8')),'hex') IS DISTINCT FROM item->>'view_sha256' THEN
          RAISE EXCEPTION 'H0 view definition mismatch: %',item->>'name';
        END IF;
      ELSE
        FOREACH role_name IN ARRAY ARRAY['anon','authenticated'] LOOP
          FOREACH privilege_name IN ARRAY ARRAY['SELECT','INSERT','UPDATE','DELETE','TRUNCATE','REFERENCES','TRIGGER'] LOOP
            IF has_table_privilege(role_name,obj,privilege_name) THEN RAISE EXCEPTION 'H0 unexpected effective client privilege'; END IF;
          END LOOP;
        END LOOP;
        FOREACH privilege_name IN ARRAY ARRAY['SELECT','INSERT','UPDATE'] LOOP
          IF NOT has_table_privilege('swarm_command',obj,privilege_name) THEN RAISE EXCEPTION 'H0 missing command privilege'; END IF;
        END LOOP;
        FOREACH privilege_name IN ARRAY ARRAY['DELETE','TRUNCATE','REFERENCES','TRIGGER'] LOOP
          IF has_table_privilege('swarm_command',obj,privilege_name) THEN RAISE EXCEPTION 'H0 broad command privilege'; END IF;
        END LOOP;
      END IF;
    ELSIF item->>'section'='guard' THEN
      obj:=to_regprocedure(item->>'name');
      SELECT jsonb_build_object('owner',pg_get_userbyid(p.proowner),'security_definer',p.prosecdef,
        'config',to_jsonb(p.proconfig),'return_type',format_type(p.prorettype,NULL),
        'language',l.lanname,'volatility',p.provolatile,'strict',p.proisstrict,
        'parallel',p.proparallel,'leakproof',p.proleakproof,'acl',p.proacl::text,
        'prosrc_sha256',encode(sha256(convert_to(p.prosrc,'UTF8')),'hex')) INTO actual
      FROM pg_proc p JOIN pg_language l ON l.oid=p.prolang WHERE p.oid=obj;
      IF actual IS DISTINCT FROM (item-'section'-'name') THEN RAISE EXCEPTION 'H0 guard mismatch: %',item->>'name'; END IF;
    ELSIF item->>'section'='dependency_index' THEN
      obj:=to_regclass('swarm.'||(item->>'name'));
      SELECT jsonb_build_object('valid',i.indisvalid,'ready',i.indisready,'unique',i.indisunique,
        'definition',pg_get_indexdef(i.indexrelid)) INTO actual FROM pg_index i WHERE i.indexrelid=obj;
      IF actual IS DISTINCT FROM (item-'section'-'name') THEN RAISE EXCEPTION 'H0 dependency index mismatch: %',item->>'name'; END IF;
    ELSIF item->>'section'='idempotency_constraint' THEN
      SELECT jsonb_build_object('validated',c.convalidated,'definition',pg_get_constraintdef(c.oid,true)) INTO actual
      FROM pg_constraint c WHERE c.conrelid='swarm.idempotency_keys'::regclass AND c.conname=item->>'name';
      IF actual IS DISTINCT FROM (item-'section'-'name') THEN RAISE EXCEPTION 'H0 idempotency constraint mismatch'; END IF;
    ELSE RAISE EXCEPTION 'unknown H0 catalog section';
    END IF;
  END LOOP;
END;
$h0catalog$;
